class IndexVisitor(ast.NodeVisitor):
    def __init__(self,path):
        self.path=path;self.stack=[];self.rows=[]
    def visit_FunctionDef(self,node):
        self.stack.append(node.name);self.generic_visit(node);self.stack.pop()
    visit_AsyncFunctionDef=visit_FunctionDef
    def visit_Constant(self,node):
        if type(node.value) in (int,float):
            self.rows.append((node.lineno,'.'.join(self.stack) or '<модуль>',repr(node.value)))

def generate():
    lines=['# Построчный индекс числовых литералов\n',
      'Каждое исполняемое числовое вхождение в файлах .py приведено отдельно. Одинаковые значения в разных контекстах могут иметь разный смысл. Номер строки соответствует версии кода, с которой собран индекс. Отрицательный литерал в AST состоит из знака операции и положительного числа: контекст строки сохраняет знак. Числа внутри строковых подписей, цветов, спецификаторов формата, имён файлов и документации не являются числовыми AST-узлами; они объяснены в §9 [основного разбора](constants-explained.md).\n']
    count=0
    paths=sorted(ROOT.glob('*.py'))+sorted((ROOT/'tests').glob('*.py'))
    for path in paths:
        name=path.relative_to(ROOT).as_posix();src=path.read_text().splitlines();visitor=IndexVisitor(path);visitor.visit(ast.parse('\n'.join(src)))
        lines+=['## '+name+'\n',RATIONALES.get(name,'Структурные числа реализации и форматирования; см. основной разбор.')+'\n','| Строка | Функция | Литерал | Код и обоснование |','| --- | --- | --- | --- |']
        for line,function,value in visitor.rows:
            why=SPECIFIC.get(function.split('.')[-1],RATIONALES.get(name,''))
            context=src[line-1].strip().replace('|','&#124;').replace('`',"'")
            lines.append(f'| {line} | {function} | {value} | `{context}` — {why} |');count+=1
        lines.append('')
    lines.append(f'Всего в этой версии: **{count} числовых вхождений**, {len(paths)} Python-файлов. Это индекс объяснений, а не заявление об экспериментальной оптимальности каждого числа.\n')
    (ROOT/'constants-index.md').write_text('\n'.join(lines),encoding='utf-8')
    s=json.loads((ROOT/'results/constants_study/study.json').read_text())
    descriptions={
      'model_parameters':('Параметры модели','Изменяется по одному параметру при прочих классических. std_x вычислена на конечном хвосте, это не классификатор хаоса. max_real_eigen_Cplus относится только к C+, не ко всей траектории. «—» означает отсутствие C+ при rho≤1.'),
      'initial_states':('Начальные состояния','Нулевое состояние — точное равновесие, начальная скорость равна нулю. Иные точки задают другие задачи Коши, а не разную точность одного метода.'),
      'short_intervals':('Длина короткого интервала','Максимум ошибки возникает рано: одинаковые значения на нескольких интервалах — реальный результат, а не ошибка копирования. Порядок по трём малым h.'),
      'horizons':('Полный горизонт','Ошибка — расхождение с численным эталоном, после потери фазы нельзя трактовать её как точность относительно точного решения. Увеличение горизонта увеличивает стоимость, но также может быть полезно для других задач.'),
      'tolerances':('Допуски RK45','Общая сетка на [0,2], контроль DOP853 3e−14/1e−15. Одновременно изменяются rtol и atol с указанными значениями; это сравнение пар, не независимая оценка эффекта каждого допуска. Время — медиана.'),
      'perturbations':('Величина возмущения','actual_delta — фактически представленная разность, не запрошенное число. Пустое first_above_one означает, что порог не достигнут до T=40; пустой наклон означает недостаток ненулевых данных.'),
      'windows':('Окно наклона ln d','Один и тот же расчёт RK4 и возмущение 1e−8, разные окна. Данные позволяют увидеть зависимость вывода от окна; это не спектр Ляпунова.'),
      'discard_times':('Удаление начала на рисунках','Доля и дисперсия приведены только как характеристики оставшегося конечного массива; граница 5 не сертифицирует стационарность.'),
      'distance_thresholds':('Условный порог расстояния','Порог меняет только диагностический момент, а не динамику или определение хаоса.'),
      'fit_points':('Сколько последних точек включить в наклон','Все успешные точки исходной серии при соответствующем количестве. Для Эйлера доступно только четыре, поскольку h=.04 не дал конечного решения.'),
      'timings':('Повторения измерения времени','Отдельные серии по 1,3,7 запусков, реальное машинное время. Не оценка статистической сходимости медианы и не гарантия, что 7 обязательно даст лучший результат на другой машине.'),
      'jacobian_difference':('Приращение для численного Якобиана','Центральная разность по каждой координате в точке [2.3,−1.4,8.1]. Полиномиальная структура Лоренца устраняет здесь ошибку усечения; при уменьшении eps видна ошибка округления.'),
      'eigen_thresholds':('Порог нулевых вещественных частей','inconclusive означает, что выбранный порог не позволяет применить критерий устойчивости. Это не вывод об устойчивости. Большой порог .1 скрывает Reλ≈.094.'),
      'grid_tolerances':('Порог проверки делимости интервала','accepted — результат одной проверки isclose, а не изменение траектории. near_noninteger специально показывает принятие очень малого несовпадения.'),
      'test_error_margins':('Пороги тестов','Измеренная ошибка, установленный порог и их отношение. Отношение >1 оставляет запас; само по себе оно не доказывает, что порог лучший.'),
      'image_resolution':('Разрешение PNG','Настоящие изображения сохранены рядом с таблицей. save_seconds не измеряет качество и зависит от машины. Численная траектория одинакова.'),
      'animation_sampling':('Кадры и частота GIF','Расчёт временной разметки кадров, а не рендер девяти новых GIF. duration=frames/fps — номинальная длительность; Pillow может квантовать длительности до сотых секунды. Строка каждого кадра включает все накопленные точки интегратора.')}
    text=['# Экспериментальная проверка констант\n','Таблицы сгенерированы из реальных расчётов `parameter_study.py`; источники — `results/constants_study/*.csv` и `study.json`. Пустые значения не заменялись искусственными числами. Пояснения выбора и ограничения: [constants-explained.md](constants-explained.md).\n','Версии: '+str(s['versions'])+'\n','![Компромиссы настроек](results/constants_study/constant_tradeoffs.png)\n']
    def value(x):
        if x is None:return '—'
        if type(x) is float:return f'{x:.9g}'
        return str(x)
    for name,(title,explanation) in descriptions.items():
        rows=s[name];headers=list(rows[0]);text+=['## '+title+'\n',explanation+'\n','| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']
        for row in rows:text.append('| '+' | '.join(value(row[h]) for h in headers)+' |')
        text.append('')
    text+=['## Шаг основного RK4: исходная серия\n','Эти результаты взяты из основного summary.json, а не пересчитаны с изменёнными параметрами. Вычислений на коротком интервале четыре на шаг; сравнение количества вызовов точное, без шумов таймера.\n','| h | Максимальная ошибка [0,2] | Вызовы f на [0,2] | Вызовы f на [0,40] |','| --- | --- | --- | --- |']
    original=json.loads((ROOT/'results/summary.json').read_text())
    for row in original['convergence']:
        if row['method']=='rk4':
            h=row['h'];text.append(f"| {h} | {value(row['max_error'])} | {4*round(2/h)} | {4*round(40/h)} |")
    (ROOT/'constants-results.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
    print('Индекс:',count,'числовых вхождений;',len(descriptions),'таблиц исследования')

if __name__=='__main__':generate()
